using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Security.Cryptography;using System.Text.RegularExpressions;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Services {
 public sealed partial class DesktopService {
  public Func<string,string[],int,Encoding,string> QueryOverride;
  sealed class LocalRevision {public string Hash;}
  readonly System.Runtime.CompilerServices.ConditionalWeakTable<object,LocalRevision> localRevisions=new System.Runtime.CompilerServices.ConditionalWeakTable<object,LocalRevision>();
  static string Revision(string content){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(content)));}
  public T Local<T>(string name,Func<T> fallback){string path=Path.Combine(Root,"config",name+".json");string raw=File.Exists(path)?GuntConfiguration.ReadShared(path):null;T value=raw==null?fallback():Json.Deserialize<T>(raw);if(value!=null)localRevisions.GetValue(value,x=>new LocalRevision{Hash=raw==null?"missing":Revision(raw)});return value;}
  public void SaveLocal(string name,object value){if(!new[]{"developer","development-sessions","commands","smart-automation","launchpad"}.Contains(name))throw new ArgumentException("지원하지 않는 개발 설정입니다.");using(var mutex=new Mutex(false,ScopedMutex("Config-"+name))){if(!mutex.WaitOne(10000))throw new IOException("다른 화면에서 개발 설정을 저장하고 있습니다.");try{string path=Path.Combine(Root,"config",name+".json");LocalRevision previous;if(!localRevisions.TryGetValue(value,out previous))throw new InvalidOperationException("최신 개발 설정을 다시 읽은 뒤 저장하세요.");string current=File.Exists(path)?Revision(GuntConfiguration.ReadShared(path)):"missing";if(current!=previous.Hash)throw new InvalidOperationException("다른 화면에서 설정이 변경됐습니다. 덮어쓰지 않았습니다. 편집 값을 확인한 뒤 다시 열어 주세요.");string raw=Json.Serialize(value);GuntConfiguration.Atomic(Root,path,raw,true);if(GuntConfiguration.ReadShared(path)!=raw)throw new IOException("개발 설정 저장 결과를 확인하지 못했습니다.");previous.Hash=Revision(raw);}finally{mutex.ReleaseMutex();}}}
  public DeveloperStore Developer(){var d=Local("developer",()=>new DeveloperStore());if(d==null||d.SchemaVersion!=1||d.Roots==null||d.Defaults==null||d.ScanDepth<1||d.ScanDepth>5||d.Tools==null)throw new InvalidDataException("개발 설정 형식을 확인하세요. 원본은 보존했습니다.");return d;}
  public void SaveDeveloper(DeveloperStore d){if(d.ScanDepth<1||d.ScanDepth>5)throw new ArgumentException("탐색 깊이는 1–5입니다.");ValidatePreferences(d.Defaults);if(!new[]{"windows-terminal","cmd"}.Contains(d.Defaults.TerminalHost)||!new[]{"codex","opencode"}.Contains(d.Defaults.DefaultAiCli))throw new ArgumentException("전역 터미널 호스트와 기본 AI CLI를 선택하세요.");foreach(var p in d.Roots)if(!Path.IsPathRooted(p)||p.IndexOfAny(new[]{'\0','\n','\r'})>=0)throw new ArgumentException("프로젝트 루트 경로 형식을 확인하세요.");foreach(var t in d.Tools){if(!Regex.IsMatch(t.Id??"",@"^[a-zA-Z0-9_-]{1,80}$")||String.IsNullOrWhiteSpace(t.Name)||!File.Exists(t.Executable)||!t.Executable.EndsWith(".exe",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("추가 도구는 이름과 실제 .exe 경로를 확인하세요.");}if(d.Tools.Select(x=>x.Id).Distinct().Count()!=d.Tools.Count)throw new ArgumentException("도구 ID가 중복됩니다.");SaveLocal("developer",d);}
  public static void ValidateDirectory(string path){if(String.IsNullOrWhiteSpace(path)||!Path.IsPathRooted(path)||path.IndexOfAny(new[]{'\0','\r','\n','"'})>=0||!Directory.Exists(path))throw new ArgumentException("존재하는 절대 폴더 경로를 선택하세요. 없는 폴더를 만들거나 다른 위치로 실행하지 않습니다.");}
  public void ValidatePreferences(DeveloperPreferences p){if(p==null)return;if(!String.IsNullOrEmpty(p.TerminalHost)&&!new[]{"windows-terminal","cmd"}.Contains(p.TerminalHost))throw new ArgumentException("터미널 호스트를 확인하세요.");if(!String.IsNullOrEmpty(p.DefaultAiCli)&&!new[]{"codex","opencode"}.Contains(p.DefaultAiCli))throw new ArgumentException("AI CLI를 확인하세요.");foreach(var text in new[]{p.WslDistribution,p.WslUser,p.CodexExecutable,p.OpenCodeExecutable})if(text!=null&&(text.Length>256||text.IndexOfAny(new[]{'\0','\r','\n'})>=0))throw new ArgumentException("WSL 이름·실행 경로에 잘못된 문자가 있습니다.");if(!String.IsNullOrEmpty(p.Editor)&&p.Editor!="vscode")throw new ArgumentException("현재 편집기는 설치된 Windows VS Code를 사용합니다.");}
  public DeveloperPreferences Preferences(ProjectEntry p){var result=Json.Deserialize<DeveloperPreferences>(Json.Serialize(Developer().Defaults));if(p.Developer!=null)foreach(var field in typeof(DeveloperPreferences).GetProperties()){var value=field.GetValue(p.Developer,null) as string;if(!String.IsNullOrEmpty(value))field.SetValue(result,value,null);}ValidatePreferences(result);return result;}
  public void SelectProject(string id){if(!Projects().Any(p=>p.Id==id))throw new ArgumentException("등록된 프로젝트를 선택하세요.");var d=Developer();if(d.SelectedProjectId==id)return;d.SelectedProjectId=id;SaveDeveloper(d);}
  public ProjectEntry ActiveProject(){var d=Developer();var p=Projects().FirstOrDefault(x=>x.Id==d.SelectedProjectId);if(p==null)throw new ArgumentException("개발 세팅에서 사용할 프로젝트를 먼저 선택하세요.");ValidateDirectory(p.Directory);return p;}
  public void RegisterRoot(string path){ValidateDirectory(path);var d=Developer();path=Path.GetFullPath(path);if(!d.Roots.Any(x=>String.Equals(x.TrimEnd('\\'),path.TrimEnd('\\'),StringComparison.OrdinalIgnoreCase)))d.Roots.Add(path);SaveDeveloper(d);}
  public void RemoveRoot(string path){var d=Developer();d.Roots.RemoveAll(x=>String.Equals(x,path,StringComparison.OrdinalIgnoreCase));SaveLocal("developer",d);}
  public ProjectEntry RegisterDiscovered(ProjectEntry p){ValidateDirectory(p.Directory);var same=Projects().FirstOrDefault(x=>String.Equals(Path.GetFullPath(x.Directory).TrimEnd('\\'),Path.GetFullPath(p.Directory).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase));if(same!=null)return same;SaveProject(p);return p;}
  public ProjectEntry[] DiscoverProjects(){var d=Developer();var found=Projects().ToList();var seen=new HashSet<string>(found.Select(x=>Path.GetFullPath(x.Directory).TrimEnd('\\')),StringComparer.OrdinalIgnoreCase);var queue=new Queue<Tuple<string,int>>();foreach(var path in d.Roots)if(Directory.Exists(path))queue.Enqueue(Tuple.Create(path,0));int visited=0;while(queue.Count>0&&visited<5000){var current=queue.Dequeue();string[] children;try{children=Directory.GetDirectories(current.Item1);}catch(UnauthorizedAccessException){continue;}catch(IOException){continue;}foreach(var dir in children){if(++visited>5000)break;try{var info=new DirectoryInfo(dir);if((info.Attributes&FileAttributes.ReparsePoint)!=0||new[]{".git","node_modules",".venv","__pycache__"}.Contains(info.Name)||(!d.ShowHidden&&((info.Attributes&FileAttributes.Hidden)!=0||info.Name.StartsWith("."))))continue;if(seen.Add(dir.TrimEnd('\\'))){string id;using(var sha=SHA256.Create())id="folder-"+BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(dir.ToUpperInvariant()))).Replace("-","").Substring(0,16);found.Add(new ProjectEntry{Id=id,Name=info.Name,Directory=dir,Ide="vscode",Terminal="powershell",Commands=new List<string>()});}if(current.Item2+1<d.ScanDepth)queue.Enqueue(Tuple.Create(dir,current.Item2+1));}catch(UnauthorizedAccessException){}catch(IOException){}}}return found.OrderByDescending(x=>x.Pinned).ThenBy(x=>x.Name).ToArray();}
  public string ProjectType(string path){ValidateDirectory(path);var types=new List<string>();foreach(var f in new[]{new[]{"package.json","Node.js"},new[]{"pnpm-lock.yaml","pnpm"},new[]{"pyproject.toml","Python"},new[]{"requirements.txt","Python"},new[]{"Cargo.toml","Rust"},new[]{"go.mod","Go"},new[]{"Dockerfile","Docker"}})if(File.Exists(Path.Combine(path,f[0])))types.Add(f[1]);if(Directory.EnumerateFiles(path,"*.sln").Any()||Directory.EnumerateFiles(path,"*.csproj").Any())types.Add(".NET");if(Directory.Exists(Path.Combine(path,".git"))||File.Exists(Path.Combine(path,".git")))types.Add("Git");return types.Count==0?"일반 폴더":String.Join(" · ",types.Distinct());}
  public static string NativeArgument(string value){return Regex.IsMatch(value??"",@"^[A-Za-z0-9_./:=+~\-]+$")?value:Quote(value);}
  public string Query(string exe,string[] args,int timeout=15000,Encoding encoding=null){if(QueryOverride!=null)return QueryOverride(exe,args,timeout,encoding);using(var p=new Process()){p.StartInfo=new ProcessStartInfo(exe,String.Join(" ",args.Select(NativeArgument))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=encoding??Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};p.Start();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(timeout)){try{p.Kill();}catch{}throw new TimeoutException("조회 제한 시간을 넘었습니다. 조회용 프로세스만 종료했습니다.");}if(p.ExitCode!=0)throw new IOException("조회 실패: "+Redact(error.Result.Trim()));return output.Result;}}
  public string ScopedMutex(string name){using(var sha=SHA256.Create())return "Local\\GUNT-"+name+"-"+BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Path.GetFullPath(Root).ToUpperInvariant()))).Replace("-","").Substring(0,16);}
  string GitExecutable(){string configured=AppPath("git");if(QueryOverride!=null||Path.GetFileName(configured).Equals("git.exe",StringComparison.OrdinalIgnoreCase))return configured;string folder=Path.GetDirectoryName(configured);foreach(string relative in new[]{@"cmd\git.exe",@"bin\git.exe",@"mingw64\bin\git.exe"}){string candidate=Path.Combine(folder,relative);if(File.Exists(candidate))return candidate;}throw new FileNotFoundException("Git GUI는 있지만 조회용 git.exe를 찾지 못했습니다.");}
  readonly Dictionary<string,ProjectInfo> gitCache=new Dictionary<string,ProjectInfo>(StringComparer.OrdinalIgnoreCase);
  public ProjectInfo GitStatus(ProjectEntry p,bool force=false){ValidateDirectory(p.Directory);ProjectInfo value;lock(gitCache){if(!force&&gitCache.TryGetValue(p.Directory,out value)&&DateTimeOffset.Now-value.Refreshed<TimeSpan.FromSeconds(15))return value;}value=new ProjectInfo{Type=ProjectType(p.Directory),Refreshed=DateTimeOffset.Now};try{string git=GitExecutable();string[] prefix={"--no-optional-locks","-c","core.fsmonitor=false","-c","core.untrackedCache=false","-C",p.Directory};value.Repository=Query(git,prefix.Concat(new[]{"rev-parse","--show-toplevel"}).ToArray()).Trim();try{value.Branch=Query(git,prefix.Concat(new[]{"symbolic-ref","--quiet","--short","HEAD"}).ToArray()).Trim();}catch{value.Branch="분리된 HEAD";}string output=QueryRawGit(git,prefix.Concat(new[]{"status","--porcelain=v1","-z","--untracked-files=all","--ignore-submodules=all"}).ToArray());var parts=output.Split('\0');for(int i=0;i<parts.Length;i++){string line=parts[i];if(line.Length<3)continue;if(line.StartsWith("??"))value.Untracked++;else value.Modified++;if(line[0]=='R'||line[0]=='C'||line[1]=='R'||line[1]=='C')i++;}}catch(Exception e){value.Error=e.Message;}lock(gitCache){gitCache[p.Directory]=value;}return value;}
  string QueryRawGit(string exe,string[] args){return Query(exe,args);}
  public string[] Distributions(){string output=Query("wsl.exe",new[]{"--list","--quiet"},20000,Encoding.Unicode);return output.Replace("\0","").Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim('\uFEFF',' ','\t')).Where(x=>x.Length>0).Distinct().ToArray();}
  void CheckDistribution(string distro){if(String.IsNullOrEmpty(distro)||!Distributions().Contains(distro,StringComparer.Ordinal))throw new ArgumentException("설치된 WSL 배포판을 선택하세요.");}
  public static string Posix(string s){if(s==null||s.IndexOf('\0')>=0)throw new ArgumentException("Linux 인수를 확인하세요.");return "'"+s.Replace("'","'\"'\"'")+"'";}
  public Func<string,string,string> WslUserResolver;
  public string[] WslUsers(string distro){CheckDistribution(distro);string path=@"\\wsl.localhost\"+distro+@"\etc\passwd";if(!File.Exists(path))throw new IOException("WSL 사용자 목록을 읽을 수 없습니다. 배포판을 직접 열고 일반 계정을 확인하세요.");return File.ReadAllLines(path).Select(x=>x.Split(':')).Where(x=>x.Length>=7&&x[2]!="65534"&&Int32.Parse(x[2])>=1000&&!x[6].Contains("nologin")&&!x[6].EndsWith("/false")).Select(x=>x[0]).ToArray();}
  public string WslUser(string distro,string preferred=null){if(WslUserResolver!=null)return WslUserResolver(distro,preferred);string requested=preferred??Developer().Defaults.WslUser;if(!String.IsNullOrEmpty(requested)){if(requested=="root"||!Regex.IsMatch(requested,@"^[a-zA-Z_][a-zA-Z0-9_-]{0,63}$"))throw new ArgumentException("일반 WSL 계정 이름을 입력하세요.");if(!WslUsers(distro).Contains(requested))throw new ArgumentException("선택한 배포판의 일반 계정을 확인하세요.");return requested;}var users=WslUsers(distro);using(var registry=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Lxss")){if(registry!=null)foreach(string id in registry.GetSubKeyNames())using(var item=registry.OpenSubKey(id)){if(Convert.ToString(item.GetValue("DistributionName"))!=distro)continue;int uid=Convert.ToInt32(item.GetValue("DefaultUid",0));string passwd=@"\\wsl.localhost\"+distro+@"\etc\passwd";foreach(var line in File.ReadAllLines(passwd)){var p=line.Split(':');if(p.Length>=3&&p[2]==uid.ToString()&&users.Contains(p[0]))return p[0];}}}if(users.Length==1)return users[0];throw new ArgumentException("배포판의 기본 계정이 일반 사용자가 아니거나 여러 계정이 있습니다. 개발 설정에서 WSL 일반 계정을 지정하세요.");}
  public string WslQuery(string distro,string script,string user=null){return Query("wsl.exe",new[]{"--distribution",distro,"--user",WslUser(distro,user),"--exec","/bin/sh","-c",script},30000);}
  public string WslPath(string directory,string distro,string preferredUser=null){ValidateDirectory(directory);CheckDistribution(distro);string account=WslUser(distro,preferredUser);string path=Query("wsl.exe",new[]{"--distribution",distro,"--user",account,"--exec","wslpath","-a","-u",directory},30000).TrimEnd('\r','\n');if(!path.StartsWith("/")||path.IndexOfAny(new[]{'\r','\n','\0'})>=0)throw new IOException("WSL에서 경로를 변환하지 못했습니다.");string user=WslQuery(distro,"id -un",account).Trim();if(user=="root")throw new ArgumentException("선택한 WSL의 기본 계정이 root입니다. 일반 Linux 계정을 설정한 뒤 사용하세요.");WslQuery(distro,"test -d "+Posix(path)+" && test -x "+Posix(path),account);return path;}
  string InteractiveQuery(string distro,string script,string user=null){return Query("wsl.exe",new[]{"--distribution",distro,"--user",WslUser(distro,user),"--cd","~","--exec","/bin/sh","-c","exec \"${SHELL:-/bin/sh}\" -ic \"$1\"","gunt",script},30000);}
  public WslTool ProbeTool(string distro,string name,string configured=null,string user=null){CheckDistribution(distro);string command=String.IsNullOrEmpty(configured)?name:configured;if(command.IndexOfAny(new[]{'\0','\n','\r'})>=0)throw new ArgumentException("실행 경로를 확인하세요.");var tool=new WslTool{Name=name};try{string response=InteractiveQuery(distro,"p=$(command -v "+Posix(command)+") && test -f \"$p\" && test -x \"$p\" && printf '\\n__GUNT_PATH__%s\\n' \"$p\" && \"$p\" --version",user);var marker=response.IndexOf("__GUNT_PATH__",StringComparison.Ordinal);if(marker<0)throw new IOException("실행 파일을 찾지 못했습니다.");string[] lines=response.Substring(marker+13).Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);tool.Executable=lines[0];tool.Version=lines.Length>1?lines[1]:"버전 응답 없음";tool.Available=true;}catch(Exception e){tool.Error=e.Message;}return tool;}
  public WslTool[] EnvironmentTools(string distro){return new[]{ProbeTool(distro,"git"),ProbeTool(distro,"node"),ProbeTool(distro,"python3"),ProbeTool(distro,"codex",Developer().Defaults.CodexExecutable),ProbeTool(distro,"opencode",Developer().Defaults.OpenCodeExecutable)};}
  public string[] WslArguments(ProjectEntry p,string action,DeveloperPreferences prefs){string linux=WslPath(p.Directory,prefs.WslDistribution,prefs.WslUser);string command="exec \"${SHELL:-/bin/sh}\" -i";if(action!="wsl"){var probe=ProbeTool(prefs.WslDistribution,action,action=="codex"?prefs.CodexExecutable:prefs.OpenCodeExecutable,prefs.WslUser);if(!probe.Available)throw new InvalidOperationException("선택한 WSL 환경에서 "+(action=="codex"?"Codex":"OpenCode")+"를 찾을 수 없습니다.\nWSL 환경에서 로그인 사용자의 PATH와 실행 파일 경로를 확인하세요.");command="cd -- "+Posix(linux)+" && printf '\\nGUnT_0x9 · %s\\n' \"$PWD\" && "+Posix(probe.Executable)+"; r=$?; printf '\\n종료 코드: %s\\n' \"$r\"; exec \"${SHELL:-/bin/sh}\" -i";}
   string encoded=Convert.ToBase64String(Encoding.UTF8.GetBytes(command));return new[]{"--distribution",prefs.WslDistribution,"--user",WslUser(prefs.WslDistribution,prefs.WslUser),"--cd",linux,"--exec","/bin/sh","-c","exec \"${SHELL:-/bin/sh}\" -ic \"$(printf %s "+encoded+" | base64 -d)\""};}
  public void RecordDeveloperUse(ProjectEntry project,string action,DeveloperPreferences prefs,string preset=null){using(var mutex=new Mutex(false,ScopedMutex("DeveloperRecency"))){if(!mutex.WaitOne(5000))throw new IOException("최근 개발 기록 저장이 사용 중입니다.");try{var all=State("project-developer-recent");var row=all.ContainsKey(project.Id)?Json.Deserialize<Dictionary<string,object>>(Json.Serialize(all[project.Id])):new Dictionary<string,object>();row["Action"]=action;row["Time"]=DateTimeOffset.Now.ToString("o");if(action=="codex"||action=="opencode"){row["Cli"]=action;row["Distribution"]=prefs.WslDistribution;}if(preset!=null)row["Preset"]=preset;all[project.Id]=row;GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","project-developer-recent.json"),Json.Serialize(all),false);}finally{mutex.ReleaseMutex();}}}
  public string LaunchDeveloper(ProjectEntry p,string action,DeveloperPreferences prefs=null){ValidateProject(p);prefs=prefs??Preferences(p);ValidatePreferences(prefs);if(action=="ai")action=String.IsNullOrEmpty(prefs.DefaultAiCli)?"codex":prefs.DefaultAiCli;if(action=="project-terminal")action=prefs.TerminalHost=="cmd"?"cmd":"terminal";if(new[]{"codex","opencode","wsl"}.Contains(action)){string[] wsl=WslArguments(p,action,prefs);string native=String.Join(" ",wsl.Select(NativeArgument));string bootstrap="try{[Console]::Title='GUnT_0x9 · "+p.Name.Replace("'","''")+"'}catch{};$i=New-Object Diagnostics.ProcessStartInfo;$i.FileName='wsl.exe';$i.Arguments='"+native.Replace("'","''")+"';$i.UseShellExecute=$false;$p=[Diagnostics.Process]::Start($i);$p.WaitForExit();Write-Host ('종료 코드: '+$p.ExitCode)";string encoded=Convert.ToBase64String(Encoding.Unicode.GetBytes(bootstrap));if(prefs.TerminalHost=="windows-terminal"){string wt=AppPath("terminal");Launch(new ProcessStartInfo(wt,"-w new new-tab --suppressApplicationTitle --title "+Quote("GUnT_0x9 · "+p.Name)+" powershell.exe -NoProfile -NoExit -EncodedCommand "+encoded){UseShellExecute=true,WorkingDirectory=p.Directory});}else Launch(new ProcessStartInfo("cmd.exe","/d /k powershell.exe -NoProfile -EncodedCommand "+encoded){UseShellExecute=true,WorkingDirectory=p.Directory});}
   else if(action=="cmd"||action=="powershell")Launch(new ProcessStartInfo(action+".exe",action=="cmd"?"/d /k":"-NoProfile -NoExit"){UseShellExecute=true,WorkingDirectory=p.Directory});else if(action=="terminal")Launch(new ProcessStartInfo(AppPath("terminal"),"-w new -d "+Quote(p.Directory)){UseShellExecute=true,WorkingDirectory=p.Directory});else if(action.StartsWith("tool:")){var t=Developer().Tools.FirstOrDefault(x=>x.Id==action.Substring(5));if(t==null||!File.Exists(t.Executable))throw new ArgumentException("설정한 도구 실행 파일이 없습니다.");Launch(new ProcessStartInfo(t.Executable,Quote(p.Directory)){UseShellExecute=true,WorkingDirectory=p.Directory});}else if(action=="ide")Launch(new ProcessStartInfo(AppPath("code"),"--new-window "+Quote(p.Directory)){UseShellExecute=true,WorkingDirectory=p.Directory});else if(new[]{"folder","repository","command"}.Contains(action)){string result=LaunchProject(p.Id,action);RecordDeveloperUse(p,action,prefs);return result;}else throw new ArgumentException("지원하지 않는 개발 동작입니다.");RecordDeveloperUse(p,action,prefs);var recent=State("project-recent");recent[p.Id]=DateTimeOffset.Now.ToString("o");GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","project-recent.json"),Json.Serialize(recent),false);GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","developer-last-tool.json"),Json.Serialize(new {ProjectId=p.Id,Action=action,Preferences=prefs,Time=DateTimeOffset.Now.ToString("o")}),false);return p.Name+" · "+action+" 대화형 실행 요청을 전달했습니다. CLI 내부 작업 완료를 의미하지 않습니다.";}
